current.custom_css:
body {
  --color-secondary: #ddd;
}

.sf-header {
  --sf-sub-item-color: #fff;
  --sf-sub-item-bg: var(--color-primary);
}

.sf-nav li.sf-menu-item--mega .sf-menu-submenu__content {
  padding-top: 20px;
}

.sf-nav li.sf-menu-item--mega .sf__menu-item-level2 .sf__sub-menu-link2 {
  display: none;
}
.sf-nav li.sf-menu-item--mega .sf__menu-item-level2 .sf__sub-menu-column {
  margin-top: 0;
}

.sf__collection-container.sidebar__fixed .sf__sidebar .sf__sidebar-content {
background: #222;
}

.scd__footer,
.scd__addon,
.scd__wrapper:not(.sf-cart) .scd__content {
  background: #222;
}

.scd__overlay {
  background: rgba(0,0,0,.5);
}

.scd-item__quantity {
  background: transparent;
  border-radius: 0;
  border: 1px solid #fff;
}

.scd-item__qty_input {
  background: transparent;
}

.sf-cart .scd__addon {
  background: #000;
}
.text-black,
.scd__addon #coupon-messages p {
  color: #fff;
}

.sf__accordion-item .sf__accordion-button:after{
background-image: var(--arrow-down-white-url);
}

.bg-white {
  background: #222;
}
.sf-nav li.sf-menu-item-parent .sf__parent-item {
  font-weight: 700;
  letter-spacing: 1px;
}

.sf-currency-switcher, .sf-language-switcher {
  font-weight: 700;
}

.sf__btn.sf__btn-link:after, .sf__btn.sf__btn-link:before, 
a.sf__btn.sf__btn-link:after, a.sf__btn.sf__btn-link:before, 
button.sf__btn.sf__btn-link:after, button.sf__btn.sf__btn-link:before {
  background: var(--color-btn-bg);
}

.sf__pcard-name {
  font-size: 18px;
  font-family: 'SF-Heading-font';
  letter-spacing: 1px;
}

.sf__pcard-price .prod__price {
  font-weight: 700;
}

.content__subheading {
  line-height: 1.125;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 700;
  color: var(--color-primary);
}

.content__heading {
  line-height: 1.1;
  margin-bottom: 16px;
}

.sf-hero__title {
  line-height: 1;
  margin-bottom: 5px;
}

.sf__custom-content-1 .section-my {
  margin-top: 30px;
}

.sf__custom-image-card-block-1 .sf__btn-link.sf__btn-large {
  letter-spacing: 0;
  line-height: 1;
  font-family: 'SF-Heading-font';
}

.sf__pcard.sf__pcard-style-1 .pcard-variant-option .sf__tooltip-item,
.sf__filter-wrapper .widget-filter__list .sf__tooltip-item {
  background: transparent;
}

.sf__pcard.sf__pcard-style-1 .pcard-variant-option .product-option-item,
.sf__filter-wrapper .widget-filter__list .tag-filter__color {
  box-shadow: 0 0 0 1px rgb(255 255 255 / 80%);
}

.sf-icon-box__text {
  margin-top: 15px;
}

.sf-icon-box__text h3 {
  font-size: 24px;
  line-height: 1.4;
  letter-spacing: 1px;
}

.sf-icon-box__text .rte {
  margin-bottom: 16px;
}

.sf__footer-block-title {
  font-size: 20px;
  text-transform: uppercase;
}

.sf__footer-form-newsletter,
.sf-footer form.sf__footer-form-newsletter .sf__newletter__form-input {
  color: #000;
}

.sf-footer form.sf__footer-form-newsletter .sf__newletter__form-input {
  border-radius: 0;
}

.sf__footer-form-newsletter .sf__form-submit {
  background: var(--color-btn-bg);
    color: var(--color-btn-text);
}

.sf__footer-form-newsletter .sf__form-submit:hover {
  color: var(--color-btn-text) !important;
}

.sf-header__bg,
.sf-header__dropdown-bg {
  background: var(--color-header-background);
}

.sf-header.sf-mega-active header,
.sf-header.sf-mega-active header .sf-menu-submenu__title,
.sf-header.sf-mega-active header .sf-sub-menu__link,
.sf-header.sf-mega-active .text-black {
  color: var(--color-header-text) !important;
}

.sf-header.sf-mega-active header .sf-sub-menu__link:hover {
  background: var(--color-primary) !important;
  color: #000 !important;
}

.sf__gridColumn-view a {
  background: #fff;
  color: #000;
}

.sf__gridColumn-view a.active svg, 
.sf__gridColumn-view a:hover svg {
  fill: currentColor;
}

.sf-pagination span:not(.deco).current,
.sf-pagination span:not(.deco):hover,
ul.sf__options-swatch.sf__button li a:hover,
.sf__gridColumn-view a.active, 
.sf__gridColumn-view a:hover,
.search-container form input,
.search-container form button,
.search-container form span {
  color: #000;
}

.sf-prod__info .quantity-input {
  background: transparent;
  border: 2px solid #fff;
  border-radius: 0;
  height: 50px;
}

.sf-prod__info .quantity-input input,
.quantity-input__element {
  background: transparent;
}

.prose :where(h2):not(:where([class~=not-prose] *)),
.prose :where(.text-black):not(:where([class~=not-prose] *)),
ul.sf__list-inline li a,
ul.sf__options-swatch.sf__button li a,
.sf__page-blog-single-post .text-black,
.search-container .text-black {
  color: #fff;
}

.prod__sticky-atc,
.search-container {
  background: #000;
}

.sf__pcard .background-color-expand {
  background: #1c1c1c;
}

.sf__pcard-style-2 .sf__pcard-content,
.sf__pcard-style-3 .sf__pcard-content{
  padding-bottom: 20px;
}

.sf__pcard-style-4 .sf__pcard-content .sf__pcard-quick-add .sf__btn {
  color: #fff;
  background: transparent;
}

.footer-mobile__common {
  background: #000;
}

.footer-mobile__common .footer__common-item {
  border-right-color: #1c1c1c;
}

.sf__sortmb-wrapper .sf__sortmb-list {
  background: #000;
}


@media screen and (min-width: 1440px) {
  .sf-hero__title {
    font-size:90px;
  }

  .sf-hero__text {
    font-size: 16px;
    font-weight: 700;
    margin-bottom: 30px;
    letter-spacing: 1px;
  }

  .sf__custom-image-card-block-1 .sf__btn-link.sf__btn-large { 
    font-size: 42px;
  }

  .content__heading {
    font-size: 60px;
  }

  .sf__footer-block-newsletter .sf__footer-block-title {
    font-size: 36px;
    letter-spacing: 1px;
  }
}

@media screen and (max-width: 767px) {
  .sf-hero__title {
    font-size: 34px;
  }

  .sf-hero__content {
    text-align: center;
  }

  .btn, .sf__btn {
    line-height: 23px;
  }

  .sf-hero__btn, .sf-hero__btn a {
    width: 100%;
  }

  .sf__collection-container .sf__collection-toolbar .sf__toolbar-wrapper {
    background: #000;
  }

  .sf-icon-box__icon {
    margin: 0;
  }

  .sf-icon-box__text .rte {
    margin-bottom: 5px;
  }

  .sf-icon-box__text {
    margin-top: 0;
    max-width: 80%;
  }

  .sf__custom-image-card-block-1 .sf__btn-link.sf__btn-large {
    font-size: 42px;
  }
}

.sf__gridColumn-view button {
	background-color: #222!important;
}

.sf__gridColumn-view button.active, 
.sf__gridColumn-view button:hover {
  color: #000 !important;
  background-color: var(--color-btn-bg-hover) !important;
}

.sf__gridColumn-view button.active svg, 
.sf__gridColumn-view button:hover svg {
  fill: #000 !important;
}
.contact-form input:not([type="submit"]),
.contact-form textarea {
  color: #000;
}

@media (max-width: 767px) {
body .section__heading,
body .content__heading {
	font-size: 28px !important;
	line-height: 1.4 !important;
}
}
